"""Teach syntax, demonstrate it, then trace it before a combined example.

Applied to the reviewed sequence before numbering and lecturer notes are built.
Each tiny new code example carries executable expected output for verification.
"""
import copy
PYTHON='https://docs.python.org/3/tutorial/'
def prose(title,*body,notes=''):
 return dict(title=title,kind='explanation',body='\n\n'.join(body),notes=notes,foundation_expansion=True)
def code(title,program,output,explain):
 return dict(title=title,kind='code',body='',code=program,practice_code=program,caption='Output: '+output.replace('\n','; '),expected_stdout=output+'\n',explain=explain,notes='Run the complete cell, then trace each line. Expected output:\n'+output,foundation_expansion=True)
def table(title,rows,caption):
 return dict(title=title,kind='table',body='',table=rows,caption=caption,notes='Read the rows in order. '+caption,foundation_expansion=True)

ARITHMETIC=[
 prose('Reading a Python expression','An expression is code that produces a value. In 7 + 2, the inputs are 7 and 2; the operator + tells Python to add them.','A statement is an instruction. total = 7 + 2 calculates 9, then gives it the name total. print(total) displays the stored value.','Read each symbol before running. Code is what you type; output is what Python displays. Do not type the word “Output”.'),
 table('Addition subtraction multiplication and division',[
 ['Operator','Meaning','Example and result'],['+','Add','7 + 2 gives 9'],['-','Subtract','7 - 2 gives 5'],['*','Multiply','7 * 2 gives 14'],['/','Divide','7 / 2 gives 3.5']], 'Python uses * for multiplication, not ×. / can produce a fractional result.'),
 code('Run the four arithmetic operations','print(7 + 2)\nprint(7 - 2)\nprint(7 * 2)\nprint(7 / 2)','9\n5\n14\n3.5',['Each print call displays one calculated result.','The numbers have no units until we assign a meaning to them.']),
 table('Floor division remainder and powers',[
 ['Operator','Meaning','Example and result'],['//','Floor the quotient','7 // 2 gives 3'],['%','Remainder','7 % 2 gives 1'],['**','Raise to a power','2 ** 3 gives 8']], '7 contains three groups of 2 with 1 left over: 7 = 3 × 2 + 1.'),
 prose('Reading powers signs and remainders','2 ** 3 means 2 × 2 × 2. It does not mean 2 × 3. The left value is the base; the right value is the exponent.','A leading minus makes a number negative: -7. Floor division rounds the quotient down: -7 / 2 is -3.5, so -7 // 2 is -4.','% is remainder, not percentage. To turn 75% into a fraction, calculate 75 / 100. Do not divide by zero.'),
 code('Run floor division remainder and powers','print(7 // 2)\nprint(7 % 2)\nprint(2 ** 3)\nprint(-7 // 2)\nprint(75 / 100)','3\n1\n8\n-4\n0.75',['** repeats multiplication.','A negative floor result rounds toward the smaller integer.']),
 prose('Which operation happens first','Parentheses group a calculation: do (2 + 3) before multiplying it by 4.','Powers come before multiplication and division. Multiplication, /, // and % come before addition and subtraction. Equal-level * and / run left to right.','Use parentheses when the intended grouping might be unclear. For a negative base, write (-2) ** 2. This gives 4; -(2 ** 2) gives -4.'),
 table('Trace an expression before its output',[
 ['Expression','First calculation','Result'],['2 + 3 * 4','3 * 4 gives 12','2 + 12 gives 14'],['(2 + 3) * 4','2 + 3 gives 5','5 * 4 gives 20'],['12 / 3 * 2','12 / 3 gives 4.0','4.0 * 2 gives 8.0']], 'Changing parentheses can change the answer even when the numbers stay the same.'),
 code('Check operation order','print(2 + 3 * 4)\nprint((2 + 3) * 4)\nprint(12 / 3 * 2)','14\n20\n8.0',['Read the calculation from the trace table.','Run first; then compare with the shown outputs.']),
 prose('Assigning and updating a named value','count = 2 gives the name count the value 2. = means assignment; it does not ask whether two values are equal.','count = count + 1 first reads the old value 2, calculates 3, then assigns 3 back to count.','After the update, print(count) displays 3. Re-running only the update cell changes count again; restart and run from the beginning for the shown result.'),
 code('Trace one update','count = 2\nprint(count)\ncount = count + 1\nprint(count)','2\n3',['The right side is calculated before the left side changes.']),
 prose('Numbers text and conversion','7 is an integer. 7.0 is a decimal-valued float. "7" is text because it is inside quotes. Both single and double quotes can enclose text.','"7" + "2" joins text into "72". To add those digits as numbers, convert each first: int("7") + int("2") gives 9.','int converts valid integer text; float converts valid decimal text. str turns a value into text. print displays a value; type reports its Python type.'),
 code('Compare numeric addition with text joining','print(7 + 2)\nprint("7" + "2")\nprint(int("7") + int("2"))\nprint(float("2.5"))','9\n72\n9\n2.5',['Quotes change the type and therefore what + does.','Conversion happens before the addition.'])]

DECISIONS=[
 prose('A comparison produces a Boolean value','A comparison asks a yes/no question about values. Its Python result is True or False, written with capital first letters and no quotes.','30 >= 30 asks “Is 30 at least 30?” The answer is True. 28 >= 30 gives False.','True and False have type bool. "False" is text, not the Boolean value False. Conditions use Boolean results to choose what happens next.'),
 table('Equality and difference',[
 ['Symbol','Question','Example and result'],['==','Equal values?','3 == 3 gives True'],['!=','Different values?','3 != 4 gives True']], '= assigns a value. == compares values. They have different jobs.'),
 table('Comparing sizes and boundaries',[
 ['Symbol','Question','Example and result'],['>','Greater than?','3 > 3 gives False'],['>=','Greater than or equal?','3 >= 3 gives True'],['<','Less than?','2 < 3 gives True'],['<=','Less than or equal?','3 <= 3 gives True']], 'The = part of >= and <= includes the boundary value.'),
 code('Display comparison results','reading = 30\nprint(reading == 30)\nprint(reading != 30)\nprint(reading > 30)\nprint(reading >= 30)\nprint(reading < 30)\nprint(reading <= 30)','True\nFalse\nFalse\nTrue\nFalse\nTrue',['Each comparison produces a Boolean.','No branch has run yet; print only displays the answers.']),
 prose('A condition and an if block','A condition is the question tested by an if statement. if reading >= 30: checks whether reading is at least 30.','The colon ends the header. The next line starts with four spaces; those spaces place it inside the block controlled by if.','If the condition is True, run the block. If it is False, skip it. The next line without those four spaces is outside the block and runs afterwards.'),
 code('An if statement without else','reading = 28\nif reading >= 30:\n    print("warm")\nprint("check finished")','check finished',['28 >= 30 is False, so the indented print is skipped.','The final print is outside the block.']),
 table('Trace both paths through if',[
 ['Value of reading','reading >= 30','Displayed lines'],['28','False','check finished'],['30','True','warm; check finished'],['31','True','warm; check finished']], 'Only the indented line is conditional. The outside line runs on either path.'),
 prose('else gives the other path','else means “otherwise”. It has a colon but no extra condition. Align else with its matching if.','The if block runs when its condition is True. The else block runs when that same condition is False. Only one of these blocks runs.','Both branch bodies are indented by four spaces. Returning to the left margin ends the whole decision.'),
]
LOGIC=[
 prose('Combining and reversing conditions','and asks for both conditions to be True. or asks for at least one to be True. not reverses a Boolean answer.','Use parentheses to make each comparison readable: (reading >= 20) and (reading <= 30). This is an inclusive range check.','For these lessons we combine comparisons, so their results are Boolean. Python also permits other operand types; those are not needed for the shown checks.'),
 table('and and or with Boolean inputs',[
 ['Inputs','and result','or result'],['True, True','True','True'],['True, False','False','True'],['False, True','False','True'],['False, False','False','False']], 'not True gives False; not False gives True.'),
 code('Check a permitted range','reading = 25\ninside = (reading >= 20) and (reading <= 30)\nprint(inside)\nprint((reading < 20) or (reading > 30))\nprint(not inside)','True\nFalse\nFalse',['Both range comparisons are True.','The outside-range comparisons are both False.']),
 prose('Why a zero check comes first','Python evaluates and from left to right. When the first Boolean comparison is False, it does not need to evaluate the second.','For a simple zero guard, use if denominator == 0: before the division and return or handle that case explicitly.','We will demonstrate that guard inside a function after learning how def and return work.')]

LOOPS=[
 prose('A loop repeats instructions','A loop runs a block more than once. One execution of the block is called an iteration.','for takes one item at a time from a collection. Use it when each item needs the same action.','while repeats while a condition stays True. Use it when a condition controls repetition. We will trace each kind before using it in a calculation.'),
 prose('Read every part of a for header','In for reading in readings:, for introduces repetition, reading names the current item, and readings is the collection to visit.','in connects the current-item name to that collection. The colon begins the loop body. Four spaces mark each instruction that repeats.','reading is a name we choose; it is assigned the next item automatically. It is not the same name as readings. After the last item, execution leaves the loop.'),
 code('Visit each item without calculating','readings = [2, 4, 6]\nfor reading in readings:\n    print(reading)\nprint("finished")','2\n4\n6\nfinished',['The body runs once for each item.','The final line is outside the loop, so it runs once.']),
 table('Trace the for loop item by item',[
 ['Step','Current reading','Action'],['First item','2','Print 2'],['Second item','4','Print 4'],['Third item','6','Print 6'],['No items left','No new item','Leave loop; print finished']], 'An empty list runs the body zero times. It still reaches the outside line.'),
 prose('Updating a counter inside a loop','A counter records how many times an event happens. Set count = 0 before the loop, then count = count + 1 inside it.','count += 1 is a shorter spelling for that numeric update. Similarly, total += reading means total = total + reading.','The initial value belongs outside the loop. Resetting count to zero inside every iteration loses the earlier count.'),
 code('Count the visited items','count = 0\nfor reading in [2, 4, 6]:\n    count += 1\nprint(count)','3',['Updates: 0 to 1, 1 to 2, then 2 to 3.']),
]
WHILE=[
 prose('A while loop checks before each repetition','while count < 3: tests the condition before entering its indented block. True enters the block; False skips it and continues after the loop.','At the end of the body, return to the condition and test again. Unlike for, while does not automatically move to the next list item.','Something must make the condition become False, or the loop may continue indefinitely. In our example, count increases on every iteration.'),
 code('A while loop with a stopping condition','count = 0\nwhile count < 3:\n    print(count)\n    count = count + 1\nprint("finished")','0\n1\n2\nfinished',['Initialise, test, run the body, update, test again.','When count becomes 3, the condition is False.']),
 table('Trace the while condition and update',[
 ['count before test','count < 3','Body and next count'],['0','True','Print 0; update to 1'],['1','True','Print 1; update to 2'],['2','True','Print 2; update to 3'],['3','False','Skip body; print finished']], 'If count starts at 3, the body runs zero times. The condition is tested first.'),
 prose('Preventing an endless loop','If the update is missing, count remains 0. The question 0 < 3 stays True, so the body keeps running.','In Colab, click the running cell’s stop button or use Runtime → Interrupt execution. Fix the condition or update before running again.','Do not run an intentionally endless example. Trace the unchanged value on the slide to see why it would fail.'),
 table('Choosing if for or while',[
 ['Construct','Purpose','When it finishes'],['if / else','Choose a path once','After the chosen block'],['for','Visit supplied items','When items are exhausted'],['while','Repeat while True','When condition becomes False']], 'A condition alone does not imply repetition: if tests once; while tests again after its body.'),
 prose('range supplies a sequence of integers','range(3) supplies 0, 1 and 2. The stop value 3 is excluded. range(1, 4) supplies 1, 2 and 3.','Use range with for when a numbered repetition is useful. The loop still works by taking the next supplied item.','range(0, 6, 2) uses a step of 2 and supplies 0, 2, 4. A step is the change between successive numbers; it cannot be zero.'),
 code('Repeat with range','for attempt in range(1, 4):\n    print(attempt)','1\n2\n3',['Start at 1; stop before 4.']),
 prose('continue and break change a loop’s path','continue skips the rest of the current iteration, then starts the next iteration. It does not end the whole loop.','break exits the nearest enclosing loop immediately. Execution resumes after that loop.','Put the condition inside the loop with four spaces. Its action is inside that condition with eight spaces: an indented block inside another block.'),
 code('Skip one item using continue','for reading in [2, -1, 6]:\n    if reading < 0:\n        continue\n    print(reading)','2\n6',['-1 takes continue, so its print is skipped.','2 and 6 reach print.']),
 code('Stop at one item using break','for reading in [2, -1, 6]:\n    if reading < 0:\n        break\n    print(reading)','2',['-1 triggers break. The loop never visits 6.']),
 table('Trace the two loop controls',[
 ['Input','continue version','break version'],['2','Print 2','Print 2'],['-1','Skip its print','Exit loop'],['6','Print 6','Never visited']], 'Use continue only when skipping is justified by the stated data rule; do not silently discard evidence.')]

EXTRA_BEFORE={
 (3,'Positional and named inputs'):[prose('Passing inputs by position or by name','In def rectangle_area(length, width):, length and width are parameter names. A call supplies an argument value for each.','rectangle_area(3, 2) binds 3 to length and 2 to width by position. rectangle_area(width=2, length=3) binds them by name.','The = inside a named argument labels an input for the call. Both calls run the same function body with the same two values.')],
 (3,'An input check before division'):[prose('None means there is no result value','None is a Python value used here to mean “no calculated answer”. It is not zero, an empty string, or the word "None".','A function returns None explicitly with return None. A function also returns None if it reaches its end without a return value.','A caller must handle None before trying arithmetic with the result. The next example returns it for division by zero.')],
 (4,'Reading and updating a dictionary'):[prose('A missing dictionary key and get','record["reading"] requests a known field. If that key does not exist, square-bracket lookup raises KeyError.','record.get("missing", 0) asks for that key with a fallback: return 0 if it is absent. This does not add a new key.','The second input is the fallback value. Use a fallback only when the task defines what missing information should mean.')],
 (4,'Open a real CSV and inspect its first row'):[prose('What with open as source does','open("file.csv", newline="") opens a text file for reading. Use the actual supplied filename, including its .csv extension.','with manages the open file. as source gives that file object a name. Indented lines use it while it is open; leaving the block closes it.','csv.DictReader(source) reads rows using the header names as keys. list(...) collects those rows into memory before the file closes.')],
 (4,'Summaries for separate groups'):[prose('Membership in a dictionary','group in totals asks whether group is already a dictionary key. group not in totals asks whether that key is absent.','Before adding to a new group, create its total with totals[group] = 0. Then add the current record’s reading.','The outer for visits records. The inner if runs only for a new group. The addition after the if runs for every record.')],
 (5,'Build the table before asking questions'):[prose('Read the table constructor in stages','import pandas as pd loads pandas and gives it the shorter name pd. This is an alias; you could use another name consistently.','Inside pd.DataFrame(...), the dictionary keys become column names. Each list supplies that column’s values in row order.','All these column lists have the same length. At position 0, building is "A" and kwh is 2; together they form the first row.')],
 (5,'Select a column and calculate its mean'):[prose('Select first then summarise','df["kwh"] selects the energy column as a Series, which is a labelled sequence of values. Its entries are 2, 4, 5 and 7.','Store it as energy = df["kwh"]. energy.mean() adds those four values and divides by four: 18 / 4 = 4.5.','df["kwh"].mean() combines those same two steps. A dot chooses a method; parentheses call it.')],
 (5,'Calculate one total for each building'):[table('Trace a group total before using groupby',[
 ['Group','Values assigned to it','Total'],['A','2 and 4','6'],['B','5 and 7','12']], 'groupby separates rows by the building label. sum adds the kWh values inside each group.'),prose('Read each step of a pandas chain','groups = df.groupby("building") describes groups of rows with matching building labels.','energy_groups = groups["kwh"] selects the energy values within those groups. totals = energy_groups.sum() calculates one total per group.','df.groupby("building")["kwh"].sum() is the same sequence written on one line. Read it from left to right.')],
 (6,'Filling a gap adds an estimate'):[prose('Testing for None and importing one tool','value is None asks whether value is the special None object. value is not None is the opposite question. Use these tests for Python None.','This differs from ==, which compares values. Do not use is to compare ordinary numeric measurements.','from statistics import median loads just the median function. statistics is a standard Python module; median is the callable tool used below.')],
 (6,'Following a cleaning loop'):[table('Trace the duplicate-record decision',[
 ['Record ID','Already in seen?','Action'],['1, first record','No','Remember 1; keep a copy'],['1, repeated record','Yes','continue; skip this copy'],['2, next record','No','Remember 2; keep a copy']], 'This example removes repeated record IDs, not every observation from repeated equipment.')],
 (6,'Comparing groups and a distribution'):[prose('A bar chart and a histogram count different things','A bar chart has named groups. bar(["A", "B"], [13, 16]) makes one bar for each supplied group value.','A histogram divides a numeric range into intervals called bins. hist(readings, bins=2) counts readings in two intervals.','With [12, 14, 13, 18], the intervals run from 12 to 15 and 15 to 18. Counts are 3 and 1; the final interval includes the last endpoint.')],
 (6,'A compact loop is optional'):[prose('Read a list comprehension after the full loop','A list comprehension builds a new list using an expression for each visited item. [value * 2 for value in readings] doubles each reading.','Its first part says what to store; its for part says which items supply value. [2, 4, 6] becomes [4, 8, 12].','This compact spelling is optional. Use the expanded loop already taught when that is easier to explain.')],
 (8,'Rows, columns and named options'):[prose('Create an array before reading its shape','NumPy is a library for numerical arrays. import numpy as np makes its tools available through the name np.','An array stores a regular arrangement of values. np.array([[1], [2], [3]]) creates three rows with one value in each.','X.shape reports (3, 1): three rows, one column. np.array([12, 14, 16]) is one-dimensional; its shape is (3,). The comma marks a one-item tuple.')],
 (8,'Preprocessing learned from training only'):[prose('Read the pipeline tools before combining them','np.nan is NumPy’s missing-number marker. SimpleImputer(strategy="median") creates a tool that will learn each column’s median from training data.','make_pipeline(imputer, model) joins preparation to prediction in that order. pipeline.fit first learns and applies the imputer, then fits the model.','pipeline.predict applies the already learned imputer to new inputs before predicting. It does not recalculate medians from the new inputs.')],
 (8,'Two error measures'):[prose('Pair two lists using zip','zip(actual, predicted) visits matching positions together. for truth, guess in zip(...): unpacks each pair into two names.','For actual [10, 20] and predicted [12, 16], the pairs are (10, 12) and (20, 16). They describe the same observations in the same order.','zip stops at the shorter input. Check equal, nonzero lengths for these error calculations; otherwise a result could ignore observations.'),code('Inspect the pairs before measuring errors','actual = [10, 20]\npredicted = [12, 16]\nfor truth, guess in zip(actual, predicted):\n    print(truth, guess)','10 12\n20 16',['The first names receive the first pair, then the second pair.']),table('Trace absolute and squared errors',[
 ['Actual and predicted','Absolute error','Squared error'],['10 and 12','abs(-2) = 2','(-2) ** 2 = 4'],['20 and 16','abs(4) = 4','4 ** 2 = 16'],['Average','(2 + 4) / 2 = 3','(4 + 16) / 2 = 10']], 'MAE is 3. RMSE is sqrt(10), approximately 3.1623. sqrt means the nonnegative square root.')],
 (9,'Counting arbitrary paired observations'):[table('Trace the four counters',[
 ['Actual, predicted','Chosen counter','Counts: TP TN FP FN'],['1, 1','TP increases','1 0 0 0'],['1, 0','FN increases','1 0 0 1'],['0, 1','FP increases','1 0 1 1'],['0, 0','TN increases','1 1 1 1']], 'All counts start at zero. Each observation follows exactly one if/elif/else branch.')],
 (10,'Each fold takes a turn at validation'):[table('Trace three validation turns',[
 ['Turn','Fit using','Validate using'],['1','Parts B and C','Part A'],['2','Parts A and C','Part B'],['3','Parts A and B','Part C']], 'Refit preprocessing in every turn. The separate final test is not A, B or C.')],
 (11,'Two models under one protocol'):[prose('Trace the interaction-building function','Each row contains two inputs. for a, b in rows: assigns them to a and b. [a, b, a * b] builds a new row with their product as a third input.','For row [2, 3], append [2, 3, 6]. For row [4, 5], append [4, 5, 20]. The function returns the newly built list of rows.','The same function must transform both training and validation inputs. It uses no target values to construct the new feature.')],
 (12,'Sorting with a tie-break rule'):[table('Trace a tuple ranking key',[
 ['Candidate','Key: error, ms, name','Position'],['beta','(2, 5, "beta")','1: lower error'],['alpha','(3, 1, "alpha")','2: tie on error; faster'],['gamma','(3, 2, "gamma")','3: same error; slower']], 'Only eligible candidates reach ranking. If error and time tie, compare the names alphabetically.'),prose('Pass a function as the sorting key','sorted returns a new list in order. In sorted(eligible, key=rank), rank is the function itself, passed without calling it.','sorted calls rank(item) for each candidate and compares the returned tuples. Writing rank() here would call it immediately without its required input.','The original eligible list is unchanged. Check len(ordered) before using ordered[0], because an empty list has no first position.')],
}

