def expand(slides,week,cohort):
 out=[]
 for s0 in slides:
  s=copy.deepcopy(s0);title=s['title']
  if week==3 and title=='Recall and a first attempt':
   s.update(title='How to read the examples',kind='explanation',body='Each example separates the instructions you type from the output Python displays.\n\nThe lecturer explains the symbols first, then runs the example and traces its result. Keep the displayed output for revision.')
  if week==3 and title=='Arithmetic that needs care':out+=copy.deepcopy(ARITHMETIC)
  if week==3 and title=='Condition':out+=copy.deepcopy(DECISIONS);continue
  if week==3 and title=='Comparison and logic':continue
  if week==3 and title=='More than two branches':
   out.append(table('Trace both paths through if else', [['temperature','temperature >= 30','Selected output'],['28','False','below 30'],['30','True','warm'],['31','True','warm']], 'Re-run the complete previous example for each value. Exactly one branch prints.'))
  if week==3 and title=='Function':
   out.append(table('Trace the if elif else chain',[['level','Tests in order','Output'],['7','7 >= 10: False; 7 >= 5: True','medium'],['10','10 >= 10: True; stop testing','high'],['3','3 >= 10: False; 3 >= 5: False','low']], 'Python stops at the first True branch. else runs when neither test passes.'))
   out+=copy.deepcopy(LOGIC)
  if week==4 and title=='Loop and iteration':out+=copy.deepcopy(LOOPS);continue
  if week==4 and title=='A dictionary is a record with named fields':out+=copy.deepcopy(WHILE)
  out+=copy.deepcopy(EXTRA_BEFORE.get((week,title),[]))
  # Explain chains before their first code example, not after it.
  if week==5 and title=='Reading a chain one operation at a time':continue
  if week==11 and title=='Read the two-model experiment':
   s['body']=s['body'].replace('fit returns the fitted model object, so creating and fitting can appear in one expression. round(value, 6) rounds a displayed number to six decimal places.','Create the model first, then call fit on the next line. round(value, 6) rounds a displayed number to six decimal places; retain full precision for calculations.')
  if week==11 and s.get('code'):
   for key in ('code','practice_code'):
    s[key]=s.get(key,'').replace('base = LinearRegression().fit(train, y)','base = LinearRegression()\nbase.fit(train, y)').replace('extended = LinearRegression().fit(with_interaction(train), y)','extended = LinearRegression()\nextended.fit(with_interaction(train), y)')
  out.append(s)
  if week==3 and title=='Defining and calling double_value':out.append(table('Trace one function call',[
   ['Step','What Python does','Value'],['Define','Store the body; do not run it','No printed output'],['Call double_value(4)','Give parameter x the argument','x is 4'],['return x * 2','Calculate and return','8'],['Assign and print','Store returned 8 in answer; display','8']], 'return sends a value back to the caller. print displays it. These are different actions.'))
  if week==3 and title=='A function with a zero-input check':out.append(table('Trace the division guard',[
   ['Call','First test','Returned result'],['safe_share(12, 3)','3 == 0 is False','12 / 3 gives 4.0'],['safe_share(12, 0)','0 == 0 is True','None; division is skipped']], 'return ends this function call immediately. Later lines inside it do not run.'))
  if week==4 and title=='A list stores items in order':out.append(table('Trace the list changes',[
   ['Instruction','List afterwards','Displayed output'],['readings = [2, 4, 6]','[2, 4, 6]','Nothing yet'],['print(readings[0])','[2, 4, 6]','2'],['readings.append(8)','[2, 4, 6, 8]','Nothing yet'],['print(readings[1:3])','[2, 4, 6, 8]','[4, 6]']], 'len reports 4 after append. A slice excludes its stop position and leaves the original list intact.'))
  if week==4 and title=='Catch one expected conversion failure':out.append(table('Trace conversion success and failure',[
   ['Text supplied','try block','Result after except'],['"2.5"','float succeeds; skip except','2.5'],['"bad"','float raises ValueError','None assigned by except']], 'Only the named conversion failure is handled. Do not use except: pass to hide unrelated errors.'))
 for s in out:
  if s.get('foundation_expansion'):s['notes']+='\n\nReference: '+PYTHON+'introduction.html and '+PYTHON+'controlflow.html; original teaching examples.'
 return out
